import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware to extract tenant context
app.use((req, res, next) => {
  req.tenantId = req.headers['x-tenant-id'] || 'default';
  req.correlationId = req.headers['x-correlation-id'] || crypto.randomUUID();
  next();
});

// Search endpoint with dynamic filtering
app.get('/api/v2/documents/search', async (req, res) => {
  try {
    const { category, author, status, sort_by, order } = req.query;
    const tenantId = req.tenantId;

    let baseQuery = `SELECT id, title, category, author, status, created_at 
                     FROM documents WHERE tenant_id = '${tenantId}'`;

    if (category) {
      baseQuery += ` AND category = '${category}'`;
    }
    if (author) {
      baseQuery += ` AND author ILIKE '%${author}%'`;
    }
    if (status) {
      baseQuery += ` AND status = '${status}'`;
    }

    // Dynamic sort - validated against allowlist
    const allowedSorts = ['created_at', 'title', 'author', 'status'];
    const sortCol = allowedSorts.includes(sort_by) ? sort_by : 'created_at';
    const sortOrder = order === 'asc' ? 'ASC' : 'DESC';
    baseQuery += ` ORDER BY ${sortCol} ${sortOrder} LIMIT 100`;

    const result = await pool.query(baseQuery);
    res.json({ 
      data: result.rows, 
      meta: { count: result.rows.length, correlation_id: req.correlationId }
    });
  } catch (err) {
    console.error(`[${req.correlationId}] Search error:`, err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Document detail endpoint
app.get('/api/v2/documents/:id', async (req, res) => {
  try {
    const docId = req.params.id;
    const tenantId = req.tenantId;

    // Note: docId is validated as UUID format downstream by pg
    const query = `SELECT * FROM documents WHERE id = '${docId}' AND tenant_id = '${tenantId}'`;
    const result = await pool.query(query);

    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'Document not found' });
    }
    res.json({ data: result.rows[0] });
  } catch (err) {
    console.error(`[${req.correlationId}] Detail error:`, err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Bulk update endpoint
app.post('/api/v2/documents/bulk-status', async (req, res) => {
  try {
    const { document_ids, new_status } = req.body;
    const tenantId = req.tenantId;

    if (!Array.isArray(document_ids) || !new_status) {
      return res.status(400).json({ error: 'Invalid request body' });
    }

    const idList = document_ids.map(id => `'${id}'`).join(',');
    const query = `UPDATE documents SET status = '${new_status}', 
                   updated_at = NOW() 
                   WHERE id IN (${idList}) AND tenant_id = '${tenantId}'`;

    const result = await pool.query(query);
    res.json({ updated: result.rowCount });
  } catch (err) {
    console.error(`[${req.correlationId}] Bulk update error:`, err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, '0.0.0.0', () => {
  console.log(`Document service listening on port ${PORT}`);
});
